 private static void need(boolean ok,String why){if(!ok)throw new AssertionError("Programmer client step="+step+" phase="+phase+": "+why);}
 private static void ack(){PacketDistributor.sendToServer(new ProgrammerWorldFixture.Ack(step));step++;phase=0;sent=ticks;}
 private static void click(NativeProgrammerScreen screen,int id,int mouse){var b=screen.button(id);need(b.active&&b.visible,"widget active="+id);need(screen.mouseClicked(b.getX()+b.getWidth()/2D,b.getY()+b.getHeight()/2D,mouse),"actual widget click="+id);}
 private static void finish(){if(ProgrammerCanonicalMode.enabled()&&step<3){PacketDistributor.sendToServer(new ProgrammerWorldFixture.Ack(64+step));phase=30;sent=ticks;}else ack();}
 @SuppressWarnings("unchecked")private static void renderer(Minecraft mc,boolean enable){try{var field=net.minecraft.client.renderer.blockentity.BlockEntityRenderDispatcher.class.getDeclaredField("renderers");field.setAccessible(true);var dispatcher=mc.getBlockEntityRenderDispatcher();if(!enable){savedRenderers=field.get(dispatcher);var copy=new java.util.HashMap<>((java.util.Map<Object,Object>)savedRenderers);copy.remove(ProgrammerCanonicalMode.type());field.set(dispatcher,copy);}else{field.set(dispatcher,savedRenderers);savedRenderers=null;}}catch(ReflectiveOperationException failure){throw new IllegalStateException("Canonical renderer negative",failure);}}
 private static Object item(Minecraft mc){var model=mc.getItemRenderer().getModel(new net.minecraft.world.item.ItemStack(ProgrammerCanonicalMode.block()),mc.level,mc.player,0);need(model instanceof com.vandorlabs.neoforge.NativeProgrammerItemModel,"production canonical inventory model");try{var field=com.vandorlabs.neoforge.NativeProgrammerItemModel.class.getDeclaredField("bake");field.setAccessible(true);need(field.get(model)==com.vandorlabs.neoforge.programmer.client.NativeProgrammerResources.currentBake(),"item and BER share one actual atlas generation");}catch(ReflectiveOperationException failure){throw new IllegalStateException(failure);}return model;}
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!ProgrammerWorldFixture.enabled())return;var mc=Minecraft.getInstance();if(mc.player==null||mc.level==null||mc.gameMode==null)return;ticks++;if(ticks%100==0)System.out.println("[vandorlabs][programmer-world] waiting step="+step+" phase="+phase+" held="+mc.player.getMainHandItem()+" screen="+mc.screen+" marker="+mc.level.getBlockState(ProgrammerWorldFixture.ACK));need(ticks<4000,"timeout mode="+mc.gameMode.getPlayerMode()+" held="+mc.player.getMainHandItem()+" selected="+mc.player.getInventory().selected+" pos="+mc.player.position()+" screen="+mc.screen);var marker=mc.level.getBlockState(ProgrammerWorldFixture.ACK);if(!marker.is(Blocks.NOTE_BLOCK)||marker.getValue(NoteBlock.NOTE)!=step){need(ticks<sent+300,"server step did not acknowledge; mode="+mc.gameMode.getPlayerMode()+" held="+mc.player.getMainHandItem()+" marker="+marker);return;}if(step==ProgrammerWorldFixture.finalStep()){mc.options.hideGui=false;System.out.println("[vandorlabs][programmer-world] client PASS "+(Boolean.getBoolean("vandorlabs.programmerGuideCheck")?"construction capture3":"real placement/sockets/editor Program+Copy/quickmove/throw/returns/page/occlusion/tool-sneak/placedBER")+" canonical="+ProgrammerCanonicalMode.enabled()+" guideOnly="+Boolean.getBoolean("vandorlabs.programmerGuideCheck"));mc.stop();return;}
  var owner=mc.level.getBlockEntity(ProgrammerWorldFixture.ROOT) instanceof NativeProgrammerEntity tile?tile:null;
  if(ProgrammerCanonicalMode.enabled()&&phase==30){if(mc.player.position().distanceToSqr(.5,96,-3.5)>.01||ticks<sent+8)return;mc.options.hideGui=true;capture="programmer-build-"+(step+1)+".png";captured=false;phase=31;sent=ticks;return;}if(ProgrammerCanonicalMode.enabled()&&phase==31){if(captured){mc.options.hideGui=false;ack();}return;}
  if(phase==19){if(!reload.isDone()||mc.getOverlay()!=null||ticks<sent+100)return;reload.join();need(oldBake!=com.vandorlabs.neoforge.programmer.client.NativeProgrammerResources.currentBake()&&item(mc)!=oldItem,"canonical shared bake/item retire on full reload");need(mc.getBlockEntityRenderDispatcher().getRenderer(owner) instanceof NativeProgrammerBlockRenderer,"production canonical BER binding after reload");draws=skips=0;mc.options.hideGui=true;capture="programmer-placed-positive.png";captured=false;phase=20;sent=ticks;return;}
  if(step==14){if(phase==5&&mc.screen==null){ack();return;}if(!(mc.screen instanceof NativeProgrammerScreen screen)||!(mc.player.containerMenu instanceof NativeProgrammerMenu menu))return;switch(phase){case 0->{if(menu.contents().getItem(1).isEmpty()||menu.contents().getItem(2).isEmpty())return;var title=screen.titleField();title.setValue("");screen.mouseClicked(title.getX()+4,title.getY()+4,0);for(char c:"Draft only".toCharArray())screen.charTyped(c,0);need(screen.editingDraft().title().equals("Draft only"),"different actual Copy draft");phase=1;sent=ticks;}case 1->{if(!menu.tile.draft().title().equals("Draft only"))return;click(screen,8,0);phase=2;sent=ticks;}case 2->{if(!net.minecraft.world.item.ItemStack.matches(menu.contents().getItem(1),menu.contents().getItem(2)))return;mc.gameMode.handleInventoryMouseClick(menu.containerId,2,0,net.minecraft.world.inventory.ClickType.QUICK_MOVE,mc.player);phase=3;sent=ticks;}case 3->{if(!menu.contents().getItem(2).isEmpty()||!NativeChipJournal.journal(mc.player.getInventory().getItem(8)))return;mc.gameMode.handleInventoryMouseClick(menu.containerId,38,1,net.minecraft.world.inventory.ClickType.THROW,mc.player);phase=4;sent=ticks;}case 4->{if(!mc.player.getInventory().getItem(8).isEmpty())return;click(screen,7,0);phase=5;sent=ticks;}}return;}
  if(step==4&&phase==2&&mc.screen==null){ack();return;}
  if(step==4){if(!(mc.screen instanceof NativeProgrammerScreen screen)||!(mc.player.containerMenu instanceof NativeProgrammerMenu menu))return;if(phase==0){if(menu.contents().getItem(1).isEmpty()||menu.contents().getItem(0).isEmpty())return;click(screen,0,0);need(screen.editingDraft().journal(),"Journal selected");click(screen,0,1);need(!screen.editingDraft().journal(),"right click previous type");click(screen,0,0);click(screen,6,0);var title=screen.titleField();screen.mouseClicked(title.getX()+4,title.getY()+4,0);for(char c:"Player journal".toCharArray())screen.charTyped(c,0);int left=screen.button(5).getX()-15,top=screen.button(5).getY()-80;screen.mouseClicked(left+20,top+130,0);for(int i=0;i<512;i++)screen.charTyped('W',0);need(screen.editingDraft().title().equals("Player journal")&&screen.editingDraft().pages().getFirst().length()==512,"actual keyboard draft");click(screen,4,0);phase=1;sent=ticks;return;}if(phase==1&&menu.contents().getItem(1).isEmpty()&&NativeChipJournal.journal(menu.contents().getItem(2))){click(screen,7,0);phase=2;sent=ticks;}return;}
  if(phase==0){if(mc.screen!=null||mc.gameMode.getPlayerMode()!=GameType.SURVIVAL||mc.player.getInventory().selected!=0||!(step==11?NativeChipJournal.journal(mc.player.getMainHandItem())&&mc.player.getMainHandItem().getCount()==1:net.minecraft.world.item.ItemStack.matches(ProgrammerWorldFixture.held(step),mc.player.getMainHandItem()))||mc.player.position().distanceToSqr(.5,96,ProgrammerWorldFixture.actorZ(step))>.01||ticks<sent+15)return;mc.options.keyShift.setDown(step==8);mc.player.setShiftKeyDown(step==8);mc.player.connection.send(new net.minecraft.network.protocol.game.ServerboundPlayerCommandPacket(mc.player,step==8?net.minecraft.network.protocol.game.ServerboundPlayerCommandPacket.Action.PRESS_SHIFT_KEY:net.minecraft.network.protocol.game.ServerboundPlayerCommandPacket.Action.RELEASE_SHIFT_KEY));phase=10;sent=ticks;return;}
  if(phase==10){if(ticks<sent+5)return;if(step==9){if(ProgrammerCanonicalMode.enabled()){need(mc.getBlockEntityRenderDispatcher().getRenderer(owner) instanceof NativeProgrammerBlockRenderer,"actual production canonical BER");oldItem=item(mc);oldBake=com.vandorlabs.neoforge.programmer.client.NativeProgrammerResources.currentBake();reload=mc.reloadResourcePacks();phase=19;sent=ticks;return;}draws=skips=0;mc.options.hideGui=true;capture="programmer-placed-positive.png";captured=false;phase=20;sent=ticks;return;}var target=ProgrammerWorldFixture.target(step);double dx=target.x-mc.player.getX(),dy=target.y-mc.player.getEyeY(),dz=target.z-mc.player.getZ();float yaw=(float)-Math.toDegrees(Math.atan2(dx,dz)),pitch=(float)-Math.toDegrees(Math.atan2(dy,Math.sqrt(dx*dx+dz*dz)));mc.player.setYRot(yaw);mc.player.setXRot(pitch);mc.player.connection.send(new net.minecraft.network.protocol.game.ServerboundMovePlayerPacket.Rot(yaw,pitch,mc.player.onGround()));mc.gameRenderer.pick(1);need(mc.hitResult instanceof BlockHitResult,"actual block ray");var hit=(BlockHitResult)mc.hitResult;if(step==0)need(hit.getBlockPos().equals(ProgrammerWorldFixture.SUPPORT),"actual support ray="+hit);else if(step==6)need(mc.level.getBlockState(hit.getBlockPos()).is(Blocks.STONE),"nearer wall selected");else need(ProgrammerHostChecks.block().installed(mc.level,hit.getBlockPos())==owner,"actual authored owner ray="+hit);if(step==1||step==2||step==10||step==11||step==12||step==15||step==16){int expectedSlot=step==1||step==16?0:step==2||step==11||step==15?1:2;var selected=ProgrammerHostChecks.block().trace(hit.getBlockPos(),mc.level.getBlockState(hit.getBlockPos()),mc.player.getEyePosition(),mc.player.getEyePosition().add(mc.player.getLookAngle().scale(mc.player.blockInteractionRange())));need(selected!=null&&selected.slot()==expectedSlot,"actual authored socket ray expected="+expectedSlot+" got="+selected+" eye="+mc.player.getEyePosition());}var result=mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,hit);System.out.println("[vandorlabs][programmer-world] action step="+step+" result="+result+" hit="+hit.getBlockPos());phase=1;sent=ticks;return;}
  if(owner==null)return;switch(step){case 0->{if(mc.player.getMainHandItem().getCount()==1&&owner.visual().slots().get(0).kind()==0)finish();}case 1->{if(mc.player.getMainHandItem().getCount()==1&&owner.visual().slots().get(0).kind()==2)finish();}case 2->{if(mc.player.getMainHandItem().getCount()==1&&owner.visual().slots().get(1).kind()==2)finish();}case 3,7,8,13->{if(mc.screen instanceof NativeProgrammerScreen)ack();}case 10->{if(owner.visual().slots().get(2).kind()==0&&NativeChipJournal.journal(mc.player.getMainHandItem()))ack();}case 11->{if(owner.visual().slots().get(1).kind()==2&&mc.player.getMainHandItem().isEmpty())ack();}case 12->{if(owner.visual().slots().get(2).kind()==2&&owner.visual().slots().get(2).company()==2&&mc.player.getMainHandItem().isEmpty())ack();}case 15->{if(owner.visual().slots().get(1).kind()==0&&NativeChipJournal.journal(mc.player.getMainHandItem()))ack();}case 16->{if(owner.visual().slots().get(0).kind()==0&&mc.player.getMainHandItem().getCount()==1&&NativeChipJournal.journal(mc.player.getInventory().getItem(9)))ack();}case 5->{if(owner.journalView()!=null&&owner.journalView().page==1)ack();}case 6->{if(ticks>sent+12){need(owner.journalView()!=null&&owner.journalView().page==1,"wall leaves page unchanged");ack();}}case 9->{if(phase==20&&captured){if(ProgrammerCanonicalMode.enabled())renderer(mc,false);else need(draws>0,"placed BER actually dispatched");enabled=false;capture="programmer-placed-disabled.png";captured=false;phase=21;sent=ticks;}else if(phase==21&&captured){if(ProgrammerCanonicalMode.enabled()){need(mc.getBlockEntityRenderDispatcher().getRenderer(owner)==null,"production BER actually disabled");renderer(mc,true);}else need(skips>0,"negative actually suppresses dispatched BER");enabled=true;mc.options.hideGui=false;ack();}}}
 }
